{"code": "const [g1, g2, g3] = await Promise.all([
  tools.grep({ pattern: "S1824|S1802", path: "tmp/sheaf/xif/paper" }),
  tools.grep({ pattern: "UnitCoherence|S1840", path: "AUDIT_LEDGER.md" }),
  tools.grep({ pattern: "S1824|S1840|UnitCoherence", path: "coord" })
]);
const uniq = (arr) => [...new Set(arr)];
console.log("--- paper refs ---");
console.log(uniq(g1.matches.map(m => m.path)).join("\n"));
console.log("--- ledger ---");
console.log(g2.matches.map(m => `${m.lineNumber}: ${m.line.trim()}`).join("\n").slice(0, 4000));
console.log("--- coord ---");
console.log(g3.matches.map(m => `${m.path}:${m.lineNumber}: ${m.line.trim()}`).join("\n").slice(0, 6000));
", "description": "Search references to S1824 and S1840"}

